/**
 * Lanza y explota dinamita con animación fluida, blindaje de obsidiana, destrucción de estructuras y actualización dirty.
 *
 * FÍSICA Y DESTRUCCIÓN:
 * 1. Destrucción de Bloques Y Estructuras:
 *    - Vaciado de la rejilla (mc.grid) y retirada limpia de estructuras estampadas (mc.structures).
 *    - Las estructuras en el radio de impacto se detectan por su AABB y se destruyen en su respectivo anillo de onda.
 * 2. Blindaje de Obsidiana:
 *    - Bloques y estructuras de obsidiana (o inamovibles) son 100% inmunes.
 *    - Oclusión radial: bloques y estructuras detrás de obsidiana quedan protegidos dentro del cono de sombra.
 * 3. Actualización Dirty Desacoplada (60 FPS estables):
 *    - Bucle desacoplado en requestAnimationFrame que remalla con mcRemeshAround una sola vez por frame.
 * 4. Fusión Visible Garantizada:
 *    - Los bloques pasan obligatoriamente por el estado visual de fuego/lava antes de desaparecer.
 * 5. Deduplicación Anti-Recursiva:
 *    - Cada TNT (bloque o estructura) detona exactamente una vez (_activeTNTCoords).
 */
var o = (typeof opts !== 'undefined' && opts) ? opts : {};

// Estado global compartido
const _activeTNTCoords = (window._activeTNTCoords = window._activeTNTCoords || new Set());
const _meltingCells = (window._tntMeltingCells = window._tntMeltingCells || new Set());
const _obsIdCache = new Map();

let _dirtyBox = null;
let _tntBurstActive = false;
let _burstTimer = null;

function markDirty(x, z) {
    x = Math.floor(x);
    z = Math.floor(z);
    if (!_dirtyBox) {
        _dirtyBox = { x0: x, z0: z, x1: x, z1: z };
    } else {
        if (x < _dirtyBox.x0) _dirtyBox.x0 = x;
        else if (x > _dirtyBox.x1) _dirtyBox.x1 = x;
        if (z < _dirtyBox.z0) _dirtyBox.z0 = z;
        else if (z > _dirtyBox.z1) _dirtyBox.z1 = z;
    }
}

function tntRenderLoop() {
    if (_dirtyBox) {
        const { x0, z0, x1, z1 } = _dirtyBox;
        _dirtyBox = null;
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(x0, z0, x1, z1);
        } else if (typeof mcFlushBuild === 'function') {
            mcFlushBuild();
        }
    }

    if (_tntBurstActive && (window._tntActiveWaves || 0) > 0) {
        requestAnimationFrame(tntRenderLoop);
    } else {
        stopTNTBurst();
    }
}

function startTNTBurst() {
    if (!_tntBurstActive) {
        _tntBurstActive = true;
        if (typeof beginBatch === 'function') beginBatch();
        if (_burstTimer) clearTimeout(_burstTimer);
        _burstTimer = setTimeout(stopTNTBurst, 15000);
        requestAnimationFrame(tntRenderLoop);
    }
}

function stopTNTBurst() {
    if (!_tntBurstActive) return;
    _tntBurstActive = false;
    if (_burstTimer) {
        clearTimeout(_burstTimer);
        _burstTimer = null;
    }
    if (_dirtyBox) {
        const { x0, z0, x1, z1 } = _dirtyBox;
        _dirtyBox = null;
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(x0, z0, x1, z1);
        }
    }
    if (typeof endBatch === 'function') {
        endBatch();
    }
    if (typeof mcDirtyHeader === 'function') mcDirtyHeader();
    if (typeof mcScheduleSave === 'function') mcScheduleSave();
    _meltingCells.clear();
}

function isObsidian(x, y, z) {
    if (typeof getVoxel !== 'function') return false;
    const v = getVoxel(x, y, z);
    if (!v) return false;

    if (typeof v === 'number') {
        const cached = _obsIdCache.get(v);
        if (cached !== undefined) return cached;
        let esObs = false;
        if (typeof mc !== 'undefined' && mc) {
            if (mc.inamovibleDoc && mc.inamovibleDoc[v]) {
                esObs = true;
            } else if (mc.blockKey && mc.blockKey[v]) {
                const k = String(mc.blockKey[v]).toLowerCase();
                if (k.includes('obsidian') || k.includes('obsidiana')) esObs = true;
            }
        }
        if (!esObs && typeof mcMatName === 'function') {
            const nm = mcMatName(v);
            if (nm && /obsidia/i.test(String(nm))) esObs = true;
        }
        _obsIdCache.set(v, esObs);
        return esObs;
    }

    if (typeof v === 'string') {
        return /obsidia/i.test(v);
    }
    return false;
}

function isStructureObsidian(s) {
    if (!s || !s.key) return false;
    const k = String(s.key).toLowerCase();
    if (k.includes('obsidian') || k.includes('obsidiana')) return true;
    if (typeof mc !== 'undefined' && mc && mc.inamovibleDoc) {
        if (mc.inamovibleDoc[s.key] || mc.inamovibleDoc[s.key.replace(/^asset:/, '')]) {
            return true;
        }
    }
    return false;
}

function rayIntersectsAABB(cx, cy, cz, tx, ty, tz, aabb) {
    const minX = aabb[0], minY = aabb[1], minZ = aabb[2];
    const maxX = aabb[3], maxY = aabb[4], maxZ = aabb[5];
    const dx = tx - cx, dy = ty - cy, dz = tz - cz;

    let tmin = 0, tmax = 1;
    if (Math.abs(dx) > 1e-6) {
        const t1 = (minX - cx) / dx, t2 = (maxX - cx) / dx;
        tmin = Math.max(tmin, Math.min(t1, t2));
        tmax = Math.min(tmax, Math.max(t1, t2));
    } else if (cx < minX || cx > maxX) return false;

    if (Math.abs(dy) > 1e-6) {
        const t1 = (minY - cy) / dy, t2 = (maxY - cy) / dy;
        tmin = Math.max(tmin, Math.min(t1, t2));
        tmax = Math.min(tmax, Math.max(t1, t2));
    } else if (cy < minY || cy > maxY) return false;

    if (Math.abs(dz) > 1e-6) {
        const t1 = (minZ - cz) / dz, t2 = (maxZ - cz) / dz;
        tmin = Math.max(tmin, Math.min(t1, t2));
        tmax = Math.min(tmax, Math.max(t1, t2));
    } else if (cz < minZ || cz > maxZ) return false;

    return tmin <= tmax && tmax >= 0.05 && tmin <= 0.95;
}

// Trazado de rayo radial hacia el objetivo optimizado con Set O(1) y AABB de estructuras
function isRayBlockedByObsidian(cx, cy, cz, tx, ty, tz, obsSet, obsidianStructs) {
    if (obsidianStructs && obsidianStructs.length > 0) {
        for (let j = 0; j < obsidianStructs.length; j++) {
            const os = obsidianStructs[j];
            const a = os.aabb || [os.ox, os.oy, os.oz, os.ox, os.oy, os.oz];
            if (rayIntersectsAABB(cx, cy, cz, tx, ty, tz, a)) return true;
        }
    }

    if (!obsSet || obsSet.size === 0) return false;
    const dx = tx - cx;
    const dy = ty - cy;
    const dz = tz - cz;
    const distSq = dx * dx + dy * dy + dz * dz;
    if (distSq <= 1) return false;

    const dist = Math.sqrt(distSq);
    const step = 0.25;
    const numSteps = Math.floor(dist / step);
    let lastX = cx, lastY = cy, lastZ = cz;

    for (let i = 1; i < numSteps; i++) {
        const t = (i * step) / dist;
        const vx = Math.round(cx + dx * t);
        const vy = Math.round(cy + dy * t);
        const vz = Math.round(cz + dz * t);

        if (vx === cx && vy === cy && vz === cz) continue;
        if (vx === tx && vy === ty && vz === tz) break;
        if (vx === lastX && vy === lastY && vz === lastZ) continue;
        lastX = vx; lastY = vy; lastZ = vz;

        if (obsSet.has(vx + ',' + vy + ',' + vz)) {
            return true;
        }
    }
    return false;
}

function handleStructBreak(s) {
    if (!s || !s.key) return;
    const sKey = String(s.key);
    const isTNT = sKey.toLowerCase().includes('tnt');

    if (isTNT) {
        const tntKey = Math.floor(s.ox) + ',' + Math.floor(s.oy) + ',' + Math.floor(s.oz);
        if (!_activeTNTCoords.has(tntKey)) {
            _activeTNTCoords.add(tntKey);
            const delay = 25 + Math.floor(Math.random() * 25);
            setTimeout(() => {
                executeSphericalExplosion(s.ox, s.oy, s.oz, 6, 1.5, {
                    waveMs: 40,
                    fireMat: 'hormig-n-naranja',
                    isChained: true
                });
                _activeTNTCoords.delete(tntKey);
            }, delay);
        }
    } else if (typeof game !== 'undefined' && game.bloques && typeof game.bloques.info === 'function') {
        try {
            const info = game.bloques.info(s.key);
            if (info && typeof info.alRomper === 'function') {
                info.alRomper({ x: s.ox, y: s.oy, z: s.oz, tipo: 'estructura', clave: s.key, ori: s.rot | 0 });
            }
        } catch (e) {}
    }
}

function throwAndExplodeTNT(startX, startY, startZ, options = {}) {
    const radius = options.radius || 4;
    const force = options.force || 1.0;
    const fuseTime = options.fuseTimeMs != null ? options.fuseTimeMs : 2000;
    const tntMat = options.tntMat || 'hab:likelava';
    const isChained = !!options.isChained;

    const tntKey = Math.floor(startX) + ',' + Math.floor(startY) + ',' + Math.floor(startZ);
    if (_activeTNTCoords.has(tntKey)) return;
    _activeTNTCoords.add(tntKey);

    const endY = startY;
    if (!isChained && typeof setVoxel === 'function') {
        setVoxel(startX, endY, startZ, tntMat);
        markDirty(startX, startZ);
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(startX, startZ);
        }
    }
    console.log(`🧨 Dinamita lanzada a (${startX}, ${endY}, ${startZ}). Mecha: ${fuseTime}ms`);

    setTimeout(() => {
        executeSphericalExplosion(startX, endY, startZ, radius, force, options);
        _activeTNTCoords.delete(tntKey);
    }, fuseTime);
}

function executeSphericalExplosion(centerX, centerY, centerZ, radius, force, options = {}) {
    const startTime = performance.now();
    const waveMs = options.waveMs != null ? options.waveMs : 40;
    const showFire = options.fire !== false;
    const fireMat = options.fireMat || 'hormig-n-naranja';

    const cx = Math.floor(centerX);
    const cy = Math.floor(centerY);
    const cz = Math.floor(centerZ);

    const radiusSq = radius * radius;
    const canRead = typeof getVoxel === 'function';

    // 0. Pre-filtro rápido de obsidiana (bloques y estructuras)
    const obsidianFound = [];
    for (let x = cx - radius; x <= cx + radius; x++) {
        for (let y = cy - radius; y <= cy + radius; y++) {
            for (let z = cz - radius; z <= cz + radius; z++) {
                const dx = x - cx, dy = y - cy, dz = z - cz;
                if (dx * dx + dy * dy + dz * dz > radiusSq) continue;
                if (isObsidian(x, y, z)) {
                    obsidianFound.push([x, y, z]);
                }
            }
        }
    }

    const obsidianStructs = [];
    const structRings = [];

    // Escaneo de estructuras (mc.structures)
    if (typeof mc !== 'undefined' && mc && mc.structures && mc.structures.length > 0) {
        const allStructs = mc.structures.slice();
        for (let i = 0; i < allStructs.length; i++) {
            const s = allStructs[i];
            if (!s) continue;
            const a = s.aabb || [s.ox, s.oy, s.oz, s.ox, s.oy, s.oz];
            const closeX = Math.max(a[0], Math.min(cx, a[3]));
            const closeY = Math.max(a[1], Math.min(cy, a[4]));
            const closeZ = Math.max(a[2], Math.min(cz, a[5]));

            const dx = closeX - cx, dy = closeY - cy, dz = closeZ - cz;
            const distSq = dx * dx + dy * dy + dz * dz;
            if (distSq > radiusSq) continue;

            if (isStructureObsidian(s)) {
                obsidianStructs.push(s);
            }
        }
    }

    const hasObsidian = obsidianFound.length > 0 || obsidianStructs.length > 0;
    const obsSet = obsidianFound.length > 0 ? new Set(obsidianFound.map(([ox, oy, oz]) => ox + ',' + oy + ',' + oz)) : null;

    // Clasificar estructuras destructibles en anillos según distancia
    let structsToDestroy = 0;
    if (typeof mc !== 'undefined' && mc && mc.structures && mc.structures.length > 0) {
        const allStructs = mc.structures.slice();
        for (let i = 0; i < allStructs.length; i++) {
            const s = allStructs[i];
            if (!s || isStructureObsidian(s)) continue;
            const a = s.aabb || [s.ox, s.oy, s.oz, s.ox, s.oy, s.oz];
            const closeX = Math.max(a[0], Math.min(cx, a[3]));
            const closeY = Math.max(a[1], Math.min(cy, a[4]));
            const closeZ = Math.max(a[2], Math.min(cz, a[5]));

            const dx = closeX - cx, dy = closeY - cy, dz = closeZ - cz;
            const distSq = dx * dx + dy * dy + dz * dz;
            if (distSq > radiusSq) continue;

            // Comprobar blindaje de obsidiana sobre la estructura
            if (hasObsidian && isRayBlockedByObsidian(cx, cy, cz, closeX, closeY, closeZ, obsSet, obsidianStructs)) {
                continue;
            }

            const impactPower = 1.0 - (distSq / radiusSq);
            const effectiveImpact = impactPower * force;
            if (effectiveImpact > 0.4 || Math.random() < effectiveImpact) {
                const d = Math.min(radius, Math.floor(Math.sqrt(distSq)));
                (structRings[d] || (structRings[d] = [])).push(s);
                structsToDestroy++;
            }
        }
    }

    // 1. PRECÁLCULO DE BLOQUES: agrupar en anillos concéntricos
    const rings = [];
    const avisos = [];
    let blocksToDestroy = 0;

    for (let x = cx - radius; x <= cx + radius; x++) {
        for (let y = cy - radius; y <= cy + radius; y++) {
            for (let z = cz - radius; z <= cz + radius; z++) {

                const dx = x - cx, dy = y - cy, dz = z - cz;
                const distanceSq = dx * dx + dy * dy + dz * dz;
                if (distanceSq > radiusSq) continue;

                const k = x + ',' + y + ',' + z;
                if (_meltingCells.has(k)) continue;

                if (canRead && !getVoxel(x, y, z)) continue;

                if (isObsidian(x, y, z)) continue;

                if (hasObsidian && isRayBlockedByObsidian(cx, cy, cz, x, y, z, obsSet, obsidianStructs)) continue;

                const impactPower = 1.0 - (distanceSq / radiusSq);
                const effectiveImpact = impactPower * force;

                if (effectiveImpact > 0.5 || Math.random() < effectiveImpact) {
                    const d = Math.floor(Math.sqrt(distanceSq));
                    (rings[d] || (rings[d] = [])).push([x, y, z]);
                    _meltingCells.add(k);

                    if (!_activeTNTCoords.has(k)) {
                        const avisa = (typeof game !== 'undefined' && game.bloques && typeof game.bloques.avisoDeRotura === 'function')
                            ? game.bloques.avisoDeRotura(x, y, z)
                            : null;
                        if (avisa) (avisos[d] || (avisos[d] = [])).push(avisa);
                    }
                    blocksToDestroy++;
                }
            }
        }
    }

    const totalToDestroy = blocksToDestroy + structsToDestroy;
    if (totalToDestroy === 0) return;

    console.log(`💥 Detonación en (${cx}, ${cy}, ${cz}). Radio ${radius}. ${blocksToDestroy} bloques + ${structsToDestroy} estructuras.`);

    window._tntActiveWaves = (window._tntActiveWaves || 0) + 1;
    startTNTBurst();

    let prevFire = null;
    let prevAvisos = null;
    const maxSteps = Math.max(rings.length, structRings.length);

    // 2. ANIMACIÓN CON DESTRUCCIÓN DE BLOQUES Y ESTRUCTURAS
    function wave(d) {
        let dar = [];

        // Apagar el frente anterior: lava -> aire
        if (prevFire) {
            for (const [x, y, z] of prevFire) {
                setVoxel(x, y, z, 0);
                markDirty(x, z);
                _meltingCells.delete(x + ',' + y + ',' + z);
            }
            dar = prevAvisos || [];
        }

        // Destruir estructuras de este anillo de distancia
        const structsNow = structRings[d] || [];
        for (let i = 0; i < structsNow.length; i++) {
            const s = structsNow[i];
            if (typeof mc !== 'undefined' && mc && mc.structures && mc.structures.includes(s)) {
                if (typeof mcEmitePolvoRotura === 'function') {
                    mcEmitePolvoRotura(s.ox, s.oy, s.oz, 0, s, 22);
                }
                if (typeof mcRemoveStruct === 'function') {
                    mcRemoveStruct(s, true);
                } else if (typeof window.mcRemoveStruct === 'function') {
                    window.mcRemoveStruct(s, true);
                }
                const a = s.aabb || [s.ox, s.oy, s.oz, s.ox, s.oy, s.oz];
                markDirty(a[0], a[2]);
                markDirty(a[3], a[5]);
                handleStructBreak(s);
            }
        }

        // Anillo actual de bloques: pintar lava
        if (d < rings.length) {
            const cells = rings[d] || [];
            if (showFire && cells.length > 0) {
                for (const [x, y, z] of cells) {
                    setVoxel(x, y, z, fireMat);
                    markDirty(x, z);
                }
                prevFire = cells;
                prevAvisos = avisos[d] || null;
            } else {
                for (const [x, y, z] of cells) {
                    setVoxel(x, y, z, 0);
                    markDirty(x, z);
                    _meltingCells.delete(x + ',' + y + ',' + z);
                }
                prevFire = null;
                prevAvisos = null;
                dar = dar.concat(avisos[d] || []);
            }
        } else {
            prevFire = null;
            prevAvisos = null;
        }

        for (const avisa of dar) avisa();

        if (d < maxSteps) {
            setTimeout(() => wave(d + 1), waveMs);
        } else {
            window._tntActiveWaves = Math.max(0, (window._tntActiveWaves || 1) - 1);
            const ms = (performance.now() - startTime).toFixed(2);
            console.log(`🔥 Explosión completa: ${totalToDestroy} elementos en ${ms}ms.`);
        }
    }

    wave(0);
}

if (typeof game !== 'undefined') {
    game.throwAndExplodeTNT = throwAndExplodeTNT;
    game.executeSphericalExplosion = executeSphericalExplosion;
}
if (typeof window !== 'undefined') {
    window.throwAndExplodeTNT = throwAndExplodeTNT;
    window.executeSphericalExplosion = executeSphericalExplosion;
}

// Hot-patch en game.bloques para reacciones en cadena limpias con onda visible y dirty updates
if (typeof game !== 'undefined' && game.bloques && typeof game.bloques.define === 'function') {
    const tntConfig = {
        nota: 'Sorpresa: explota (protegido por obsidiana)!',
        alRomper: function (c) {
            const tntKey = Math.floor(c.x) + ',' + Math.floor(c.y) + ',' + Math.floor(c.z);
            if (_activeTNTCoords.has(tntKey)) return;
            _activeTNTCoords.add(tntKey);

            const delay = 25 + Math.floor(Math.random() * 25);
            setTimeout(() => {
                executeSphericalExplosion(c.x, c.y, c.z, 6, 1.5, {
                    waveMs: 40,
                    fireMat: 'hormig-n-naranja',
                    isChained: true
                });
                _activeTNTCoords.delete(tntKey);
            }, delay);
        }
    };
    try {
        game.bloques.define('asset:assets/tnt.vox.json', tntConfig);
        game.bloques.define('hab:tnt', tntConfig);
        game.bloques.define('tnt', tntConfig);
    } catch (e) {}
}

// Hot-patch para la tecla T al apuntar
if (typeof game !== 'undefined' && typeof game.onKey === 'function') {
    game.onKey('t', () => {
        if (typeof game.aim !== 'function') return;
        const aim = game.aim();
        if (!aim) return;
        throwAndExplodeTNT(...aim, {
            radius: 8,
            force: 1.5,
            fuseTimeMs: 400,
            tntMat: 'lava',
            waveMs: 40,
            fireMat: 'hormig-n-naranja'
        });
    });
}

// Si se invocó con parámetros directos (ej. game.snippet('explosion-tnt-obsidiana', c))
if (o && typeof o.x === 'number' && typeof o.y === 'number' && typeof o.z === 'number') {
    const tntKey = Math.floor(o.x) + ',' + Math.floor(o.y) + ',' + Math.floor(o.z);
    if (!_activeTNTCoords.has(tntKey)) {
        _activeTNTCoords.add(tntKey);
        const isChained = !!(o.cfg && o.cfg.nota);
        if (isChained) {
            const delay = 25 + Math.floor(Math.random() * 25);
            setTimeout(() => {
                executeSphericalExplosion(o.x, o.y, o.z, o.radius || 6, o.force || 1.5, {
                    waveMs: o.waveMs || 40,
                    fireMat: o.fireMat || 'hormig-n-naranja',
                    isChained: true
                });
                _activeTNTCoords.delete(tntKey);
            }, delay);
        } else {
            throwAndExplodeTNT(o.x, o.y, o.z, {
                radius: o.radius || 8,
                force: o.force || 1.5,
                fuseTimeMs: o.fuseTimeMs != null ? o.fuseTimeMs : 400,
                tntMat: o.tntMat || 'lava',
                waveMs: o.waveMs || 40,
                fireMat: o.fireMat || 'hormig-n-naranja'
            });
        }
    }
} else if (typeof toast === 'function') {
    toast('🧨 TNT optimizada: Destrucción de bloques/estructuras y blindaje de obsidiana');
}

return { throwAndExplodeTNT, executeSphericalExplosion };
